const game = new GF.Game({
  id:'harbor-courier', title:'Harbor Courier', width:960, height:540,
  palette:['#16385C','#4DC6D8','#FFF3C4','#FF7C63','#37A66A'], background:'#4DC6D8', seed:481516
});

const C={navy:'#16385C',water:'#4DC6D8',cream:'#FFF3C4',coral:'#FF7C63',green:'#37A66A',road:'#f7e5ba',ink:'#19344c'};
const stops=[
  {name:'Lighthouse Cafe', color:'#FF7C63', parcel:{x:150,y:285}, target:{x:790,y:105}, route:[{x:305,y:360},{x:665,y:360},{x:790,y:105}]},
  {name:'Coral Market', color:'#37A66A', parcel:{x:150,y:285}, target:{x:790,y:430}, route:[{x:320,y:390},{x:660,y:390},{x:790,y:430}]},
  {name:'Seabreeze Hotel', color:'#4DC6D8', parcel:{x:150,y:285}, target:{x:805,y:265}, route:[{x:300,y:355},{x:670,y:355},{x:805,y:265}]}
];
const blocks=[
  {x:340,y:82,w:285,h:205,label:'Sunny Lofts',color:'#FF7C63'},
  {x:360,y:355,w:265,h:92,label:'Dockside Stores',color:'#37A66A'},
  {x:700,y:190,w:130,h:110,label:'Marina Hall',color:'#FFF3C4'},
  {x:90,y:80,w:155,h:102,label:'Post Office',color:'#FFF3C4'},
  {x:105,y:390,w:150,h:75,label:'Boat Shed',color:'#FF7C63'}
];
function rrHit(x,y,r,b){const nx=Math.max(b.x,Math.min(x,b.x+b.w)),ny=Math.max(b.y,Math.min(y,b.y+b.h));return (x-nx)*(x-nx)+(y-ny)*(y-ny)<r*r;}
function keyAny(input){return input.keys.ArrowLeft||input.keys.ArrowRight||input.keys.ArrowUp||input.keys.ArrowDown||input.keys.KeyA||input.keys.KeyD||input.keys.KeyW||input.keys.KeyS;}

const play={
  init(){this.runCount=0;},
  reset(){
    this.runCount=(this.runCount||0)+1;
    this.p={x:180,y:285,vx:0,vy:0,angle:0}; this.delivery=0; this.carry=false; this.timer=75;
    this.wp=0; this.blocked=false; this.detour=false; this.notice='Collect the color parcel!'; this.noticeT=3;
    this.sparkT=0; this.musicT=0; this.lastDirX=0; this.lastDirY=0;
    if(this.runCount>1) game.event('fresh_run_started',{run:this.runCount});
  },
  objective(){const s=stops[this.delivery]; return this.carry?s.target:s.parcel;},
  update(dt){
    const p=this.p, s=stops[this.delivery]; if(!s)return;
    this.timer=Math.max(0,this.timer-dt); this.noticeT=Math.max(0,this.noticeT-dt);
    this.musicT+=dt;
    if(this.musicT>1.15){this.musicT=0; GF.Sfx.beep({freq:this.timer<18?520:330,to:this.timer<18?580:392,dur:.06,type:'triangle',vol:.06});}
    if(this.timer<15 && Math.floor((this.timer+dt)*2)!==Math.floor(this.timer*2)) GF.Sfx.beep({freq:760,dur:.035,type:'square',vol:.11});
    if(this.timer<=0){game.flash(C.coral,.4); game.shake(6,.28); GF.Sfx.noise({dur:.3,vol:.2,freq:250}); game.gameOver({message:"TIME'S UP — DISPATCH MISSED"}); return;}
    let ix=(game.input.keys.ArrowRight||game.input.keys.KeyD?1:0)-(game.input.keys.ArrowLeft||game.input.keys.KeyA?1:0);
    let iy=(game.input.keys.ArrowDown||game.input.keys.KeyS?1:0)-(game.input.keys.ArrowUp||game.input.keys.KeyW?1:0);
    const user=keyAny(game.input);
    let gx=0,gy=0;
    let obj=this.objective();
    if(this.carry && this.wp<s.route.length){obj=s.route[this.wp]; if(GF.math.dist(p.x,p.y,obj.x,obj.y)<32)this.wp++; obj=this.wp<s.route.length?s.route[this.wp]:s.target;}
    let dx=obj.x-p.x,dy=obj.y-p.y,dl=Math.hypot(dx,dy)||1;
    gx=dx/dl; gy=dy/dl;
    if(user){let l=Math.hypot(ix,iy)||1; ix/=l;iy/=l; gx=gx*.28+ix*.72;gy=gy*.28+iy*.72;}
    const gl=Math.hypot(gx,gy)||1; gx/=gl;gy/=gl;
    const speed=user?235:170;
    p.vx+=(gx*speed-p.vx)*Math.min(1,dt*6); p.vy+=(gy*speed-p.vy)*Math.min(1,dt*6);
    const ox=p.x,oy=p.y; p.x+=p.vx*dt;p.y+=p.vy*dt;
    let hit=false; for(const b of blocks){if(rrHit(p.x,p.y,13,b)){hit=true;break;}}
    if(hit){p.x=ox;p.y=oy;p.vx*=-.25;p.vy*=-.25;this.blocked=true;this.notice='BLOCKED! Find the open street.';this.noticeT=.8;GF.Sfx.beep({freq:160,to:110,dur:.08,type:'square',vol:.12});}
    p.x=GF.math.clamp(p.x,25,935);p.y=GF.math.clamp(p.y,65,510);
    const vl=Math.hypot(p.vx,p.vy); if(vl>8)p.angle=Math.atan2(p.vy,p.vx);
    if(vl>125 && (this.lastDirX* p.vx+this.lastDirY*p.vy)<-2500 && this.sparkT<=0){game.burst(p.x,p.y,{count:4,speed:38,size:2,life:.28,colors:[C.cream],gravity:30});this.sparkT=.18;}
    this.sparkT-=dt;this.lastDirX=p.vx;this.lastDirY=p.vy;
    const active=this.objective();
    if(!this.carry && GF.math.dist(p.x,p.y,active.x,active.y)<31){
      this.carry=true;this.wp=0;game.addScore(25);this.notice='Parcel aboard — follow the beacon!';this.noticeT=2;
      game.event('courier_scooter_delivery_started',{stop:this.delivery+1,target:s.name});
      game.event('parcel_collected',{stop:this.delivery+1,score:game.score});
      game.burst(p.x,p.y,{count:12,speed:85,size:3,life:.45,colors:[s.color,C.cream],gravity:90});GF.Sfx.beep({freq:480,to:720,dur:.13,type:'triangle',vol:.24});
    }else if(this.carry && GF.math.dist(p.x,p.y,s.target.x,s.target.y)<40){this.finish(s);}
  },
  finish(s){
    const before=game.score; game.addScore(100); this.carry=false; this.delivery++;
    game.shake(4,.16);game.flash(s.color,.35);game.hitStop(.08);
    game.burst(s.target.x,s.target.y,{count:28,speed:160,size:4,life:.8,colors:[s.color,C.cream,C.green,C.coral],gravity:160});
    GF.Sfx.noise({dur:.1,vol:.16,freq:900});GF.Sfx.melody([[660,.08],[880,.1],[1100,.16]],{type:'triangle',vol:.2});
    game.event('delivery_completed',{stop:this.delivery,name:s.name,before:before,after:game.score});
    if(this.blocked){this.detour=true;game.event('route_detour_completed',{stop:this.delivery,route:'open_street'});}
    if(this.delivery>=3){game.event('third_delivery_completed',{deliveries:3,timerRemaining:Math.round(this.timer)});game.win({message:'ALL DELIVERIES COMPLETE!'});return;}
    this.timer=Math.min(75,this.timer+4);this.notice='Delivered! +4 tide-clock seconds';this.noticeT=2.2;
  },
  draw(ctx){
    const W=960,H=540;
    const g=ctx.createLinearGradient(0,0,W,H);g.addColorStop(0,'#73d9e4');g.addColorStop(1,'#2faec7');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
    ctx.globalAlpha=.3;ctx.strokeStyle='#fff3c4';ctx.lineWidth=2;for(let y=35;y<H;y+=32){ctx.beginPath();for(let x=0;x<W;x+=45)ctx.quadraticCurveTo(x+22,y+5*Math.sin((x+y+game.time*20)/50),x+45,y);ctx.stroke();}ctx.globalAlpha=1;
    ctx.fillStyle=C.road;ctx.fillRect(45,55,850,430);ctx.fillStyle='#fff8df';ctx.fillRect(55,65,830,410);
    ctx.strokeStyle='#d4b97d';ctx.lineWidth=3;ctx.setLineDash([10,10]);ctx.beginPath();ctx.moveTo(280,70);ctx.lineTo(280,470);ctx.moveTo(70,330);ctx.lineTo(870,330);ctx.stroke();ctx.setLineDash([]);
    for(const b of blocks){GF.Draw.roundRect(ctx,b.x+4,b.y+6,b.w,b.h,13,'rgba(22,56,92,.25)');GF.Draw.roundRect(ctx,b.x,b.y,b.w,b.h,13,b.color);ctx.fillStyle='rgba(255,255,255,.35)';ctx.fillRect(b.x+12,b.y+12,b.w-24,10);GF.Draw.text(ctx,b.label,b.x+b.w/2,b.y+b.h/2,{size:13,color:C.ink,weight:'800'});}
    for(let i=0;i<stops.length;i++){const s=stops[i], active=i===this.delivery;ctx.globalAlpha=active?1:.42;ctx.strokeStyle=s.color;ctx.lineWidth=active?5:3;ctx.beginPath();ctx.arc(s.target.x,s.target.y,active?31:23,0,Math.PI*2);ctx.stroke();ctx.fillStyle=s.color;ctx.beginPath();ctx.arc(s.target.x,s.target.y,12,0,Math.PI*2);ctx.fill();GF.Draw.text(ctx,['☕','M','H'][i],s.target.x,s.target.y+1,{size:14,color:'#fff'});if(active)GF.Draw.text(ctx,s.name,s.target.x,s.target.y-42,{size:14,color:C.ink,weight:'800'});ctx.globalAlpha=1;}
    const s=stops[this.delivery];if(s&&!this.carry){const q=s.parcel, pulse=1+Math.sin(game.time*5)*.12;ctx.save();ctx.translate(q.x,q.y);ctx.scale(pulse,pulse);GF.Draw.roundRect(ctx,-15,-12,30,24,4,s.color);ctx.fillStyle=C.cream;ctx.fillRect(-11,-3,22,4);ctx.restore();GF.Draw.text(ctx,'PARCEL',q.x,q.y-26,{size:12,color:C.ink});}
    if(s){const o=this.objective(),p=this.p;let ax=o.x-p.x,ay=o.y-p.y,al=Math.hypot(ax,ay)||1;ax/=al;ay/=al;const ex=480+ax*425,ey=285+ay*210;ctx.fillStyle=s.color;ctx.beginPath();ctx.arc(ex,ey,11+Math.sin(game.time*5)*2,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff';ctx.beginPath();ctx.moveTo(ex+ax*13,ey+ay*13);ctx.lineTo(ex-ay*8,ey+ax*8);ctx.lineTo(ex+ay*8,ey-ax*8);ctx.fill();}
    const p=this.p;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.angle);ctx.fillStyle='rgba(22,56,92,.22)';ctx.beginPath();ctx.ellipse(-2,7,21,10,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle=C.ink;ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(-13,0);ctx.lineTo(13,0);ctx.stroke();ctx.fillStyle=C.navy;ctx.beginPath();ctx.arc(-12,0,7,0,Math.PI*2);ctx.arc(13,0,7,0,Math.PI*2);ctx.fill();GF.Draw.roundRect(ctx,-8,-10,22,18,7,C.water);ctx.fillStyle=C.cream;ctx.fillRect(7,-6,10,4);if(this.carry){GF.Draw.roundRect(ctx,-16,-13,13,12,2,s.color);}ctx.restore();
    GF.Draw.roundRect(ctx,16,12,180,44,11,'rgba(22,56,92,.92)');GF.Draw.text(ctx,'TIDE-CLOCK',29,27,{size:12,color:C.cream,align:'left'});GF.Draw.text(ctx,Math.ceil(this.timer)+'s',181,35,{size:25,color:this.timer<15?C.coral:'#fff',align:'right'});
    GF.Draw.roundRect(ctx,210,12,330,44,11,'rgba(22,56,92,.92)');GF.Draw.text(ctx,this.carry?'DELIVER TO':'PICK UP FOR',224,27,{size:11,color:C.cream,align:'left'});GF.Draw.text(ctx,s?(this.carry?s.name:'Stop '+(this.delivery+1)+' • '+s.name):'',526,36,{size:17,color:s?s.color:'#fff',align:'right'});
    GF.Draw.roundRect(ctx,555,12,190,44,11,'rgba(22,56,92,.92)');GF.Draw.text(ctx,'DELIVERIES',570,27,{size:11,color:C.cream,align:'left'});GF.Draw.text(ctx,this.delivery+' / 3',730,36,{size:20,color:'#fff',align:'right'});
    GF.Draw.roundRect(ctx,760,12,184,44,11,'rgba(22,56,92,.92)');GF.Draw.text(ctx,'SCORE',774,27,{size:11,color:C.cream,align:'left'});GF.Draw.text(ctx,String(game.score),930,36,{size:22,color:'#fff',align:'right'});
    if(this.noticeT>0)GF.Draw.text(ctx,this.notice,480,510,{size:17,color:C.ink,weight:'800'});
    GF.Draw.vignette(ctx,W,H,.16);
  }
};
game.add('play',play);
game.titleScreen({subtitle:'Arrow Keys / WASD to drive • Collect parcels • Deliver before the tide-clock!'});
